pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Bound the amount to a reasonable range; avoid 0 since that would skip the bug.
        vm.assume(amount > 0 && amount <= 1000 ether);

        // We need two different addresses to accumulate balances.
        address actor1 = makeAddr("actor1");
        address actor2 = makeAddr("actor2");

        // Fund actor1 and actor2.
        vm.deal(actor1, amount);
        vm.deal(actor2, amount);

        // Actor1 deposits.
        vm.prank(actor1);
        c.deposit{value: amount}();

        // Actor2 deposits.
        vm.prank(actor2);
        c.deposit{value: amount}();

        // Actor1 withdraws the full amount.
        vm.prank(actor1);
        c.withdraw(amount);

        // After the withdrawal, the sum of known balances (using the public getter for the mapping)
        // must equal the contract's current ETH balance.
        // In the reference contract this holds; in the buggy version, actor1's balance
        // was decremented by amount+1, making the sum < address(c).balance.
        assertTrue(c.balances(actor1) + c.balances(actor2) == address(c).balance);
    }
}

